const size_t s2_dbc_message_count = 60;
const size_t s2_dbc_signal_count = 113;

const s2_message_def_t *s2_dbc_find_message(uint32_t can_id)
{
    size_t lo = 0, hi = s2_dbc_message_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        uint32_t id = s2_dbc_messages[mid].id;
        if (id == can_id) {
            return &s2_dbc_messages[mid];
        }
        if (id < can_id) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

const s2_message_def_t *s2_dbc_message_of_signal(uint16_t signal_index)
{
    for (size_t i = 0; i < s2_dbc_message_count; i++) {
        const s2_message_def_t *m = &s2_dbc_messages[i];
        if (signal_index >= m->first_signal && signal_index < (uint16_t)(m->first_signal + m->signal_count)) {
            return m;
        }
    }
    return NULL;
}

const s2_signal_def_t *s2_dbc_signal(uint16_t signal_index)
{
    const s2_message_def_t *m = s2_dbc_message_of_signal(signal_index);
    return m ? &m->signals[signal_index - m->first_signal] : NULL;
}

